<?php
/** JSON-driven product page sections. @package VedCare_Divine */
$product = isset( $args['product'] ) && is_array( $args['product'] ) ? $args['product'] : array();
if ( ! $product ) { return; }
$currency = static function( $amount ) { return is_numeric( $amount ) ? '₹' . number_format_i18n( (float) $amount ) : ''; };
$video_embed_url = static function( $url ) { return preg_match( '#(?:youtu\.be/|youtube\.com/(?:watch\?v=|shorts/))([A-Za-z0-9_-]{11})#', $url, $matches ) ? 'https://www.youtube.com/embed/' . $matches[1] : ''; };
$product_image = ! empty( $product['product_image'] ) ? $product['product_image'] : '';
$gallery_images = array_values( array_filter( (array) ( $product['gallery_images'] ?? array() ) ) );
if ( $gallery_images ) { $product_image = $gallery_images[0]; }
$wc_product_id = absint( $product['woocommerce']['product_id'] ?? 0 );
$purchase_url  = $wc_product_id && function_exists( 'wc_get_product' ) && wc_get_product( $wc_product_id ) ? add_query_arg( 'add-to-cart', $wc_product_id, home_url( '/' ) ) : vedcare_divine_shop_url();
$testimonials  = array();
$testimonial_file = get_theme_file_path( 'assets/data/testimonials.json' );
if ( is_readable( $testimonial_file ) ) {
	$testimonial_data = json_decode( file_get_contents( $testimonial_file ), true ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_get_contents_file_get_contents
	$filter_product = strtolower( trim( $product['testimonials']['filter_product'] ?? '' ) );
	$weight_gain_products = array( 'vedcare gold', 'vedcare build', 'vedcare build mini' );
	$is_weight_gain_product = in_array( strtolower( trim( $product['name'] ?? '' ) ), $weight_gain_products, true );
	foreach ( is_array( $testimonial_data ) ? $testimonial_data : array() as $testimonial ) {
		$testimonial_product = strtolower( trim( $testimonial['product'] ?? '' ) );
		$matches_product = $is_weight_gain_product
			? in_array( $testimonial_product, array( 'vedcare gold', 'vedcare build' ), true )
			: $filter_product === $testimonial_product;
		if ( is_array( $testimonial ) && ! empty( $testimonial['active'] ) && $matches_product && ! empty( $testimonial['image'] ) && is_readable( get_theme_file_path( 'assets/images/testimonials/' . sanitize_file_name( $testimonial['image'] ) ) ) ) { $testimonials[] = $testimonial; }
	}
}
$testimonial_count = count( $testimonials );
$testimonial_rating = $testimonial_count ? array_sum( array_map( static function( $testimonial ) { return absint( $testimonial['rating'] ?? 0 ); }, $testimonials ) ) / $testimonial_count : 0;
$benefits = array_values( array_filter( (array) ( $product['benefits'] ?? array() ), static function( $benefit ) { return false === strpos( (string) $benefit, 'where supported by official documentation' ); } ) );
$rating_value = absint( $product['rating']['value'] ?? 0 );
$customer_count_label = trim( (string) ( $product['rating']['customer_count_label'] ?? '' ) );
$transformation_images = array();
$transformation_file = get_theme_file_path( 'assets/data/transformations.json' );
if ( is_readable( $transformation_file ) ) { $transformation_data = json_decode( file_get_contents( $transformation_file ), true ); $transformation_images = array_values( array_filter( (array) ( $transformation_data[ $product['product_id'] ?? '' ] ?? array() ), static function( $image ) { return is_string( $image ) && is_readable( get_theme_file_path( $image ) ); } ) ); }
?>
