-hero__price"><strong><?php echo esc_html( $currency( $product['offer_price_inr'] ?? null ) ); ?></strong><?php if ( ! empty( $product['mrp_inr'] ) ) : ?> <del><?php echo esc_html( $currency( $product['mrp_inr'] ) ); ?></del><?php endif; ?></p><label class="product-hero__quantity"><?php esc_html_e( 'Quantity', 'vedcare-divine' ); ?><input id="vedcare-product-quantity" type="number" min="1" value="1" aria-label="<?php esc_attr_e( 'Quantity', 'vedcare-divine' ); ?>"></label><div class="product-hero__actions"><a class="button button--gold" href="<?php echo esc_url( $purchase_url ); ?>"><?php esc_html_e( 'Buy now', 'vedcare-divine' ); ?></a><a class="button button--secondary" href="<?php echo esc_url( $purchase_url ); ?>"><?php esc_html_e( 'Add to cart', 'vedcare-divine' ); ?></a></div></div></div></section>

	<section class="product-benefits"><div class="container"><div class="product-benefits__grid"><?php foreach ( array_slice( $benefits, 0, 5 ) as $benefit ) : ?><div><span aria-hidden="true">✦</span><p><?php echo esc_html( $benefit ); ?></p></div><?php endforeach; ?></div></div></section>

	<?php if ( $transformation_images ) : ?><section class="section product-transformations"><div class="container"><div class="section-heading section-heading--center"><h2><?php esc_html_e( 'Transformation Photos', 'vedcare-divine' ); ?></h2></div><div class="transformations-carousel" tabindex="0"><div class="transformations-carousel__viewport"><div class="transformations-carousel__track"><?php foreach ( $transformation_images as $index => $image ) : ?><button class="transformations-carousel__slide" type="button" data-transformation-index="<?php echo esc_attr( $index ); ?>"><img src="<?php echo esc_url( vedcare_divine_asset_url( $image ) ); ?>" alt="" loading="lazy"></button><?php endforeach; ?></div></div><button class="transformations-carousel__button transformations-carousel__button--previous" type="button" aria-label="<?php esc_attr_e( 'Previous transformation photos', 'vedcare-divine' ); ?>">‹</button><button class="transformations-carousel__button transformations-carousel__button--next" type="button" aria-label="<?php esc_attr_e( 'Next transformation photos', 'vedcare-divine' ); ?>">›</button></div></div></section><dialog class="transformations-lightbox" aria-label="<?php esc_attr_e( 'Transformation photo viewer', 'vedcare-divine' ); ?>"><button type="button" class="transformations-lightbox__close" aria-label="<?php esc_attr_e( 'Close viewer', 'vedcare-divine' ); ?>">×</button><button type="button" class="transformations-lightbox__previous" aria-label="<?php esc_attr_e( 'Previous photo', 'vedcare-divine' ); ?>">‹</button><img src="" alt=""><button type="button" class="transformations-lightbox__next" aria-label="<?php esc_attr_e( 'Next photo', 'vedcare-divine' ); ?>">›</button></dialog><?php endif; ?>

